contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address payable receiver, uint amount) public payable {
        require(msg.sender == address(c));
        bool reverted;
        if (receiver == address(0) || amount == 0) {
            try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        } else {
            // ensure c has balance so transfer cannot fail for other reasons
            if (address(c).balance < amount) {
                try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
            } else {
                c.sendTo(receiver, amount);
                reverted = false;
            }
        }
        assert(reverted == (receiver == address(0) || amount == 0 || address(c).balance < amount) || !reverted);
    }
    receive() external payable {}
}

