contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        require(amount > 0);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        // Rule: the call may only move at most `amount` out of C (or nothing on revert).
        // A faulty version that over-sends or leaks funds breaks the first conjunct;
        // one that mints/steals ETH into C breaks the second.
        assert(balAfter + amount >= balBefore && balAfter <= balBefore);
    }
    receive() external payable {}
}

