contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;

        // C holds no ether and has no payable fallback, so no positive-amount
