}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        // this contract deployed c, so it is the owner and the caller
        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.sendTo(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;

        // Self-transfer: no ether leaves C, so it succeeds iff amount <= balance,
        // and a success leaves C's balance exactly unchanged.
        assert(reverted == (amount > balanceBefore));
        assert(balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

