contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a, uint b) public payable {
        require(a > 0 && b > 0);
        require(address(this).balance >= a + b);
        // fund c with a + b extra so balance can be varied per input
        c.sendTo(address(this), 0);
        bool r1;
        bool r2;
        uint before = address(c).balance;
        // top-level state-changing calls with try/catch not allowed nested; use low-level? Use try at top level only.
        // We must use try/catch; do both at top level sequentially.
        try c.sendTo(address(this), a) { r1 = false; } catch { r1 = true; }
        try c.sendTo(address(this), b) { r2 = false; } catch { r2 = true; }
        if (a + b <= before) {
            assert(!r1 && !r2);
        } else if (a <= before) {
            assert(!r1 && r2);
        } else {
            assert(r1);
        }
    }
    receive() external payable {}
}

